<div class="form-check mb15"><input type="checkbox" class="form-check-input" id="fiscal_override_enabled" name="fiscal_override_enabled" value="1" <?php echo$override?'checked':'';?>><label for="fiscal_override_enabled">Usar configuración específica para esta venta</label><div><small>No modifica el producto maestro.</small></div></div>
