 <div class="row g-2"><div class="col-md-6"><label>ClaveProdServ SAT</label><input class="form-control" name="product_service_code" value="<?php echo esc($value('product_service_code'));?>"></div><div class="col-md-6"><label>ClaveUnidad SAT</label><input class="form-control" name="unit_code" value="<?php echo esc($value('unit_code'));?>"></div><div class="col-md-6"><label>Unidad</label><input class="form-control" name="fiscal_commercial_unit" value="<?php echo esc($value('commercial_unit'));?>"></div><div class="col-md-6"><label>Objeto de impuesto</label><input class="form-control" name="tax_object_code" value="<?php echo esc($value('tax_object_code'));?>"></div><div class="col-md-12"><label>Descripción fiscal</label><input class="form-control" name="fiscal_description" value="<?php echo esc($value('fiscal_description'));?>"></div></div>
 <h5 class="mt15">Impuestos</h5><?php foreach($taxes as$i=>$tax){?><div class="row g-2 mb5"><div class="col-md-3"><input class="form-control" name="fiscal_taxes[<?php echo$i;?>][tax_code]" value="<?php echo esc($tax['tax_code']??'');?>" placeholder="Código SAT"></div><div class="col-md-3"><select class="form-control" name="fiscal_taxes[<?php echo$i;?>][tax_type]"><option value="transfer" <?php echo($tax['tax_type']??'')==='transfer'?'selected':'';?>>Traslado</option><option value="withholding" <?php echo($tax['tax_type']??'')==='withholding'?'selected':'';?>>Retención</option></select></div><div class="col-md-3"><input class="form-control" name="fiscal_taxes[<?php echo$i;?>][factor_type]" value="<?php echo esc($tax['factor_type']??'');?>" placeholder="Factor"></div><div class="col-md-3"><input class="form-control" name="fiscal_taxes[<?php echo$i;?>][rate_or_quota]" value="<?php echo esc($tax['rate_or_quota']??'');?>" placeholder="Tasa/cuota"></div></div><?php }?>
