</div>
<script>$(function(){var codes=<?php echo json_encode(array_map(fn($x)=>['code'=>$x->code,'label'=>$x->code.' · '.$x->description],$sat_tax_codes??[]),JSON_UNESCAPED_UNICODE);?>,factors=['Tasa','Cuota','Exento'],initial=<?php echo json_encode(array_values($taxes),JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);?>,editor=$('#invoice-tax-editor'),index=0;$('#invoice-fiscal-override-fields input[name=tax_object_code]').removeAttr('name').hide();$('#invoice-fiscal-override-fields>.row.g-2.mb5').find(':input').removeAttr('name');function options(rows,value){return rows.map(function(r){var v=r.code||r;return '<option value="'+v+'" '+(v===value?'selected':'')+'>'+String(r.label||r)+'</option>';}).join('');}function add(t){t=t||{};var i=index++,row=$('<div class="invoice-tax-row border rounded p-2 mb10"><div class="row g-2"><div class="col-md-3"><label>Tipo</label><select class="form-control" name="fiscal_taxes['+i+'][tax_type]"><option value="transfer">Traslado</option><option value="withholding">Retención</option></select></div><div class="col-md-3"><label>Impuesto SAT</label><select class="form-control" name="fiscal_taxes['+i+'][tax_code]">'+options(codes,t.tax_code||'')+'</select></div><div class="col-md-2"><label>Factor</label><select class="form-control tax-factor" name="fiscal_taxes['+i+'][factor_type]">'+options(factors,t.factor_type||'Tasa')+'</select></div><div class="col-md-3"><label>Tasa/cuota</label><input class="form-control tax-rate" name="fiscal_taxes['+i+'][rate_or_quota]" value="'+String(t.rate_or_quota||'')+'" inputmode="decimal"></div><div class="col-md-1"><button type="button" class="btn btn-danger btn-sm remove-tax mt25">Eliminar</button></div></div></div>');row.find('[name$="[tax_type]"]').val(t.tax_type||'transfer');row.on('change','.tax-factor',function(){row.find('.tax-rate').prop('disabled',this.value==='Exento').val(this.value==='Exento'?'':row.find('.tax-rate').val());});row.on('click','.remove-tax',function(){row.remove();activate();});editor.append(row);}function activate(){$('#fiscal_override_enabled').prop('checked',true);$('#invoice-fiscal-override-fields').removeClass('d-none');}window.invoiceRenderFiscalTaxes=function(rows){editor.empty();index=0;(rows||[]).forEach(add);};window.invoiceRenderFiscalTaxes(initial);$('#invoice-add-tax').on('click',function(){add({});activate();});$('#invoice-fiscal-override-fields').on('change input','input,select',activate);$('#fiscal_override_enabled').on('change',function(){$('#invoice-fiscal-override-fields').toggleClass('d-none',!this.checked);});$('#invoice-tax-object-select').on('change',function(){if(this.value==='01')editor.empty();activate();});});</script>
